		</tr>
	</thead>
	<tbody>
	    <!-- add parent relationship info to the quotation_items => support hierarchical section headers -->
            <!-- format with separator lines if element is first order position (POS1), else without (POS 1.1) -->
            {# {% set ns.tableLine = "tableLine" if not item.parent_item else "" %} #}
            <!-- format bold and with separator lines for section headers -->
            {# {% set ns.tableLine = "tableLine sectionHeader" if quoteitem_is_header(item) else ns.tableLine %} #}

    		<tr class="quoteitems {# ns.tableLine #}">
		        <td class="">1</td>
			    <td class="">
                    <p>{{ _(doc.custom_description) or ""}}</p>
    			</td>
    			{% set tab_total = namespace(value=so_doc.total) %}
			    {% if doc.custom_portion > 0 and so_doc.total %}
    		        {% set tab_total.value = (doc.custom_portion / 100) * so_doc.total %}
    		    {% endif %}
    			<td class="{# ns.tableLine #} text-right">{{ frappe.format_value(tab_total.value, {"fieldtype": "Currency"})  if tab_total.value != 0 else "" }}</td>
    		</tr>

		{% set ns.tableLine = "tableLine" %}

		<tr class=" quoteitems {{ ns.tableLine }}">
			{% if so_doc.flags.show_inclusive_tax_in_print %}
				<td colspan="{{ ns.Columns }}">
					{{ _("Total Excl. Tax") }}
				</td>
				<td class="text-right">
				    {% set net_total = namespace(value=so_doc.net_total) %}
				    {% if doc.custom_portion > 0 and so_doc.net_total %}
        		        {% set net_total.value = (doc.custom_portion / 100) * so_doc.net_total %}
        		    {% endif %}
					{{ frappe.format_value(net_total.value, {"fieldtype": "Currency"}) }}
					{# {{ so_doc.get_formatted("net_total", so_doc) }} #}
				</td>
			{% else %}
				<td colspan="{{ ns.Columns }}">
					{{ _("Total") }}
				</td>
				<td class="text-right">
				    {% set total = namespace(value=so_doc.total) %}
				    {% if doc.custom_portion > 0 and so_doc.total %}
        		        {% set total.value = (doc.custom_portion / 100) * so_doc.total %}
        		    {% endif %}
					{{ frappe.format_value(total.value, {"fieldtype": "Currency"}) }}
					{# {{ so_doc.get_formatted("total", so_doc) }} #}
				</td>
			{% endif %}
		</tr>

		{%- if so_doc.discount_amount -%}
		<tr class=" quoteitems {{ ns.tableLine }}">
			<td colspan="{{ ns.Columns }}">
			    {%- if so_doc.additional_discount_percentage != 0 -%}
				    {{ _("Discount") }} ({{ so_doc.get_formatted("additional_discount_percentage") }} &percnt;)
				{% else %}
				    {{ _("Discount") }}
				{%- endif -%}    
			</td>
			<td class="text-right">
			    {% set disc_amt = namespace(value=so_doc.discount_amount) %}
			    {% if doc.custom_portion > 0 and so_doc.discount_amount %}
    		        {% set disc_amt.value = (doc.custom_portion / 100) * so_doc.discount_amount %}
    		    {% endif %}
				{{ frappe.format_value(disc_amt.value, {"fieldtype": "Currency"}) }}
			</td>
		</tr>

		<tr class="quoteitems {{ ns.tableLine }}">
			<td colspan="{{ ns.Columns }}">
			    {{ _("Net Total") }}
			</td>
			<td class="text-right">
			    {{frappe.format_value(net_total.value, {"fieldtype": "Currency"})}}
				{# {{ so_doc.get_formatted("net_total") }} #}
			</td>
		</tr>
		{%- endif -%}		

		{%- for row in so_doc.taxes -%}
		  {%- if not row.included_in_print_rate or so_doc.flags.show_inclusive_tax_in_print -%}
		  {%- if row.tax_amount >= 0 -%}
			<tr class="quoteitems {{ ns.tableLine }}">
				<td colspan="{{ ns.Columns }}">
				    {% if '%' in row.description or row.rate == 0 %}
					    {{ row.description }}
					{% else %}
					    {% set tax_rate = namespace(value=row.rate) %}
        			    {% if doc.custom_portion > 0 and row.rate %}
            		        {% set tax_rate.value = (doc.custom_portion / 100) * row.rate %}
            		    {% endif %}
					    {{ row.description }}@{{frappe.format_value(tax_rate.value, {"fieldtype": "Currency"})}}%
					{% endif %}
				</td>
				<td class="text-right">
				    {% set tax_amt = namespace(value=row.tax_amount) %}
    			    {% if doc.custom_portion > 0 and row.tax_amount %}
        		        {% set tax_amt.value = (doc.custom_portion / 100) * row.tax_amount %}
        		    {% endif %}
					{{frappe.format_value(tax_amt.value, {"fieldtype": "Currency"})}}
					{# {{ row.get_formatted("tax_amount", so_doc) }} #}
				</td>
			</tr>
		    {% endif %}
		  {%- endif -%}
		{%- endfor -%}	

		<tr class="quoteitems {{ ns.tableLine }}">
			<td colspan="{{ ns.Columns }}">
				<b>{{ _("Grand Total") }}</b>
			</td>
			<td class="text-right">
			    {% set gt = namespace(value=so_doc.grand_total) %}
			    {% if doc.custom_portion > 0 %}
    		        {% set gt.value = (doc.custom_portion / 100) * so_doc.grand_total %}
    		    {% endif %}
				<b>{{ frappe.format_value(gt.value, {"fieldtype": "Currency"}) }}</b>
			</td>
		</tr>
	</tbody>
</table>

